package com.gstory.flutter_unionad.splashad

import android.content.Context
import org.json.JSONException
import org.json.JSONObject
import android.util.Log;
import com.bytedance.sdk.openadsdk.mediation.MediationConstant
import com.bytedance.sdk.openadsdk.mediation.ad.MediationSplashRequestInfo

class AdsConfig {

    companion object {
        val yinbiao =
            "{\"cypher\":4,\"message\":\"\"}"
        val gaokao =
            "{\"cypher\":4,\"message\":\"\"}"
        val xingainianyingyu =
            "{\"cypher\":4,\"message\":\"\"}"
        val tangshi =
            "{\"cypher\":4,\"message\":\"\"}"

        fun getAdsConfig(context: Context): JSONObject {
            val packageName = context.packageName

            var configJsonObj: JSONObject? = null
            try {
                if (packageName == "com.yyybabc") {
                    configJsonObj = JSONObject(yinbiao);
                } else if (packageName == "com.yuyao.gaokao") {
                    configJsonObj = JSONObject(gaokao);
                } else if (packageName == "com.yuyao.xingainianyingyu") {
                    configJsonObj = JSONObject(xingainianyingyu);
                } else if (packageName == "com.yuyao.tangshi") {
                    configJsonObj = JSONObject(tangshi);
                }
            } catch (e: JSONException) {
                configJsonObj = JSONObject();
            }

            Log.i("TAG", "广告配置信息");
            Log.i("TAG", packageName);
            Log.i("TAG", configJsonObj.toString());


            return configJsonObj!!
        }

        fun getSplashConfig(context: Context): MediationSplashRequestInfo {
            val packageName = context.packageName
            val csjSplashRequestInfo: MediationSplashRequestInfo

            if (packageName == "com.yyybabc") {
                csjSplashRequestInfo = object : MediationSplashRequestInfo(
                    MediationConstant.ADN_PANGLE,  // 穿山甲
                    "888381860",  // adn开屏广告代码位Id，注意不是聚合广告位Id
                    "5411278",  // adn应用id，注意要跟初始化传入的保持一致
                    "" // adn没有appKey时，传入空即可
                ) {}
            } else {
                csjSplashRequestInfo = object : MediationSplashRequestInfo(
                    MediationConstant.ADN_PANGLE,  // 穿山甲
                    "",  // adn开屏广告代码位Id，注意不是聚合广告位Id
                    "",  // adn应用id，注意要跟初始化传入的保持一致
                    "" // adn没有appKey时，传入空即可
                ) {}
            }
            //第一步、创建开屏自定义兜底对象

            return csjSplashRequestInfo
        }
    }
}